#include "../source/Showroom.hpp"
#include <filesystem>
#include <fstream>
#include <cstdio>
int main(int argc,char**argv){if(argc!=3)return 2;const char* names[]={"sentinel","infernus","banshee","landstal","bravura","buffalo","cheetah","comet","elegant","sultan","elegy","stratum","flash","jester","baggage","calica"};const int ids[]={405,411,429,400,401,402,415,480,507,560,562,561,565,559,485,15183};std::vector<gt4::Entry> entries;for(int i=0;i<16;++i){gt4::Entry e;e.id=ids[i];e.modelKey=gt4::modelNameKey(names[i]);std::ifstream f(std::filesystem::path(argv[1])/(std::string(names[i])+".info"));std::string ignore;std::getline(f,ignore);std::getline(f,ignore);int count=0;f>>count;e.paints.resize(size_t(std::max(0,count)));entries.push_back(e);}std::mt19937 random{0x5245414c};const auto plan=gt4::rollPrize(entries,random,gt4::readSecretUnlocks(std::filesystem::path(argv[2]).wstring()));if(!plan)return 3;const char* model="";for(int i=0;i<16;++i)if(ids[i]==plan.id)model=names[i];std::printf("[{\"id\":%d,\"model\":\"%s\",\"style\":%d,\"paintjob\":%d,\"wheel\":%d,\"paint\":%d,\"ability\":%d,\"serial\":%u,\"modkit\":%s,\"parts\":[",plan.id,model,plan.style,plan.paintjob,plan.wheel,plan.paint,int(plan.ability),plan.serial,plan.modkit?"true":"false");bool comma=false;for(int id:gt4::prizeParts(plan)){std::printf("%s%d",comma?",":"",id);comma=true;}std::puts("]}]");}
